"""Build the unchanged API A opaque native graph for real Windows execution."""
from pathlib import Path
import argparse,hashlib,itertools,json,os,re,subprocess,tempfile
ROOT=Path(__file__).resolve().parents[2]
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def main():
	parser=argparse.ArgumentParser(description=__doc__)
	for name in ['compiler','cc','cxx','sysroot','output']:parser.add_argument('--'+name,type=Path,required=True)
	args=parser.parse_args();compiler=args.compiler.resolve();output=args.output.resolve();assert not output.is_relative_to(ROOT);output.mkdir(parents=True,exist_ok=True);work=Path(tempfile.mkdtemp(prefix='byte-api-a-windows-',dir=output));media=work/'media';media.mkdir();here=Path(__file__).resolve().parent;sources=[Path(__file__).resolve(),*[here/('api-a'+suffix) for suffix in ['-leaf.astra','-component.astra','-protocol.astra','-com-import.astra','-com-client.cpp','-client.c','-support.c']],ROOT/'lib/runtime/interop/foreign-14.c'];receipt=dict(scope='API A unchanged common source C+COM opaque graph; native Windows execution required',compiler_sha256=sha(compiler),sources={str(p.relative_to(ROOT)):sha(p) for p in sources},checks=[],products={},execution_expectations={})
	def run(command):
		assert sha(compiler)==receipt['compiler_sha256'];p=subprocess.run(list(map(str,command)),text=True,capture_output=True,cwd=work,timeout=120,env=dict(os.environ,CCACHE_DISABLE='1',PYTHONDONTWRITEBYTECODE='1'));receipt['checks'].append(dict(command=list(map(str,command)),exit=p.returncode,stdout=p.stdout,stderr=p.stderr));(work/'build.json').write_text(json.dumps(receipt,indent=2)+'\n');assert p.returncode==0,receipt['checks'][-1];return p.stdout
	selected=[compiler,'--target=x86_64-w64-windows-gnu','--foreign-personalities=c,com'];sysroot=['--sysroot='+str(args.sysroot.resolve())];cflags=['-std=c11','-Wall','-Wextra','-Werror','-pedantic'];cppflags=['-std=c++17','-Wall','-Wextra','-Werror','-pedantic','-fno-exceptions','-fno-rtti'];runtime=work/'foreign.o';support=work/'support.o';run([args.cc,*sysroot,*cflags,'-O2','-c',ROOT/'lib/runtime/interop/foreign-14.c','-o',runtime]);run([args.cc,*sysroot,*cflags,'-O2','-c',here/'api-a-support.c','-o',support])
	for levels in [*itertools.product('02',repeat=3),('1','1','1')]:
		case=work/('units-'+''.join(levels));case.mkdir();leaf=case/'leaf.astra';leaf.write_bytes((here/'api-a-leaf.astra').read_bytes());component=case/'component.astra';component.write_bytes((here/'api-a-component.astra').read_bytes());protocol=case/'protocol.astra';protocol.write_bytes((here/'api-a-protocol.astra').read_bytes());consumer=case/'consumer.astra';consumer.write_bytes((here/'api-a-com-import.astra').read_bytes())
		run([*selected,'-O'+levels[0],'-c','--module','Byte16',*[a for n in ['Byte16.Configuration','Byte16.Statistics<f64>','Byte16.Session','Byte16.Fault','Byte16.observe_retirement'] for a in ['--native-export',n]],'--emit-interface',case/'leaf.asti',leaf,'-o',case/'leaf.o']);leaf.unlink();run([*selected,'-O'+levels[1],'-c','--module','ByteService16',*[a for n in ['ByteService16.Session','ByteService16.Token','ByteService16.foreign_fault'] for a in ['--native-export',n]],'--import-module',case/'leaf.asti','--emit-interface',case/'component.asti',component,protocol,'-o',case/'component.o']);component.unlink();protocol.unlink();run([*selected,'-O'+levels[2],'-c','--import-module',case/'component.asti',consumer,'-o',case/'consumer.o']);adapter=case/'adapter.cpp';adapter.write_text(run([*selected,'--import-module',case/'component.asti','--emit-com-source',consumer]));(case/'sdk.hpp').write_text(run([*selected,'--import-module',case/'component.asti','--emit-com-header',consumer]));probe=case/'header.cpp';probe.write_text('#include "sdk.hpp"\n#include "sdk.hpp"\n');run([args.cxx,*sysroot,*cppflags,'-fsyntax-only',probe]);bridge=case/'adapter.o';run([args.cxx,*sysroot,*cppflags,'-O'+levels[2],'-c',adapter,'-o',bridge]);forwarder=case/'records.c';forwarder.write_text(run([*selected,'--import-module',case/'component.asti','--emit-class-source',consumer]));forward_obj=case/'records.o';run([args.cc,*sysroot,*cflags,'-O'+levels[2],'-c',forwarder,'-o',forward_obj]);binary=media/('byte-api-a-com-'+''.join(levels)+'.exe');run([args.cxx,*sysroot,*cppflags,'-O2','-static','-Wl,--no-insert-timestamp',here/'api-a-com-client.cpp',bridge,forward_obj,case/'leaf.o',case/'component.o',case/'consumer.o',support,runtime,'-lole32','-luuid','-o',binary]);receipt['products'][binary.name]=sha(binary);receipt['execution_expectations'][binary.name]=dict(pass_markers=['PASS API A native Windows C/COM processing, imported calls, checked outputs and exact lifetimes'])
		header=(case/'sdk.hpp').read_text();configuration_type=re.search(r'int32_t byte_service16_create\((\w+) argument0',header).group(1);statistics_type=re.search(r'virtual HRESULT STDMETHODCALLTYPE statistics\((\w+) \*result\)',header).group(1);(case/'api-com-types.h').write_text('using Native=byte_service16_handle;\nusing Oracle=byte_service16_protocol_Interface;\nusing Configuration='+configuration_type+';\nusing Statistics='+statistics_type+';\nusing Error=astra_foreign_error;\n#define score astra_field_0_score\n#define revision astra_field_1_revision\n#define processed astra_field_2_processed\n');sdk_client=case/'sdk-client.cpp';sdk_client.write_bytes((here/'api-a-com-client.cpp').read_bytes());binary=media/('byte-api-a-sdk-'+''.join(levels)+'.exe');run([args.cxx,*sysroot,*cppflags,'-O2','-DUSE_SDK','-I'+str(case),'-static','-Wl,--no-insert-timestamp',sdk_client,bridge,forward_obj,case/'leaf.o',case/'component.o',case/'consumer.o',support,runtime,'-lole32','-luuid','-o',binary]);receipt['products'][binary.name]=sha(binary);receipt['execution_expectations'][binary.name]=dict(pass_markers=['PASS API A native Windows C/COM processing, imported calls, checked outputs and exact lifetimes'])
		# The independent C oracle consumes the same opaque Windows library.
		client=case/'c-client.o';run([args.cc,*sysroot,*cflags,'-O2','-c',here/'api-a-client.c','-o',client]);binary=media/('byte-api-a-c-'+''.join(levels)+'.exe');run([args.cxx,*sysroot,*cppflags,'-O2','-static','-Wl,--no-insert-timestamp',client,bridge,forward_obj,case/'leaf.o',case/'component.o',case/'consumer.o',support,runtime,'-lole32','-luuid','-o',binary]);receipt['products'][binary.name]=sha(binary);receipt['execution_expectations'][binary.name]=dict(pass_markers=['PASS API A unique processing session: checked configuration, bounded output, statistics and independent snapshots']);assert not any(p.exists() for p in [leaf,component,protocol])
	receipt['status']='CROSS_BUILD_PASS; native Windows execution pending';(work/'build.json').write_text(json.dumps(receipt,indent=2)+'\n');print(work/'build.json')
if __name__=='__main__':main()
